from __future__ import annotations

import json
import httpx
import logging
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Dict, List, Optional
from urllib.parse import urlparse

from src.common.sitemap import SiteMap
from src.common.types import UserRole


@dataclass
class ToolConfig:
    """Configuration for tool paths, typically loaded from tool_config.json."""
    user_roles_file: str = "user_roles.json"
    sitemap_file: str = "sitemap.json"
    logfilepath: str = "pentest.log"
    proxy: Optional[str] = None

    def to_dict(self) -> Dict[str, Any]:
        """Serialize ToolConfig to a dictionary."""
        config = {
            "user_roles_file": self.user_roles_file,
            "sitemap_file": self.sitemap_file,
            "logfilepath": self.logfilepath,
        }
        if self.proxy:
            config["proxy"] = self.proxy
        return config

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "ToolConfig":
        """Create a ToolConfig from a dictionary."""
        return cls(
            user_roles_file=data.get("user_roles_file", "user_roles.json"),
            sitemap_file=data.get("sitemap_file", "sitemap.json"),
            logfilepath=data.get("logfilepath", "pentest.log"),
            proxy=data.get("proxy"),
        )

    @classmethod
    def from_file(cls, config_file: str = "tool_config.json") -> "ToolConfig":
        """Load ToolConfig from a JSON file."""
        path = Path(config_file)
        if not path.is_absolute():
            path = Path.cwd() / path

        if not path.exists():
            return cls()

        try:
            with path.open("r", encoding="utf-8") as f:
                data = json.load(f)
            return cls.from_dict(data)
        except Exception:
            return cls()

    def load_user_roles(self, base_path: Optional[Path] = None) -> List[UserRole]:
        """Load user roles from the configured file path."""
        path = Path(self.user_roles_file)
        if not path.is_absolute():
            path = (base_path or Path.cwd()) / path

        if not path.exists():
            return []

        try:
            with path.open("r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, list):
                return [UserRole.from_dict(item) for item in data]
            return []
        except Exception:
            return []


class HTTPClientTool:
    """
    Thin wrapper around httpx.Client with name-based cookie injection.

    Usage:
        client = HTTPClientTool(user_roles=roles)
        resp = client.get("/api/foo", name="john_admin")
        resp = client.post("/api/bar", json={"x": 1}, name="jane_user")
    """

    def __init__(
        self,
        user_roles: Optional[List[UserRole]] = None,
        proxy: Optional[str] = None,
        timeout: float = 30.0,
        verify: bool = False,
        follow_redirects: bool = True,
        logger: Optional[logging.Logger] = None,
        # Legacy parameter for compatibility
        sitemap: Optional[SiteMap] = None,
    ) -> None:
        self._logger = logger or logging.getLogger(__name__)

        # Create httpx client
        client_kwargs: Dict[str, Any] = {
            "follow_redirects": follow_redirects,
            "timeout": timeout,
            "verify": verify,
        }
        if proxy:
            client_kwargs["proxy"] = proxy
        self._client = httpx.Client(**client_kwargs)

        # Store user roles indexed by name (unique identifier)
        self._user_roles: Dict[str, UserRole] = {}
        self._default_name: Optional[str] = None

        if user_roles:
            for user_role in user_roles:
                # Use name as key if available, otherwise fall back to role
                key = user_role.name if user_role.name else user_role.role
                self._user_roles[key] = user_role
                if self._default_name is None:
                    self._default_name = key

        # Store sitemap for legacy baseline() method
        self._sitemap = sitemap

    @property
    def available_names(self) -> List[str]:
        """Return list of available user names for authentication."""
        return list(self._user_roles.keys())

    def _get_cookies_for_name(self, name: Optional[str], url: str) -> Dict[str, str]:
        """Get cookies dict for the specified user name, filtered by URL domain/path."""
        effective_name = name or self._default_name
        if not effective_name or effective_name not in self._user_roles:
            return {}

        user_role = self._user_roles[effective_name]
        if not user_role.cookies:
            return {}

        parsed = urlparse(url)
        host = parsed.hostname or ""
        path = parsed.path or "/"
        is_secure = parsed.scheme.lower() == "https"

        cookies = {}
        for cookie_entry in user_role.cookies:
            if not isinstance(cookie_entry, dict):
                continue

            name = cookie_entry.get("name")
            value = cookie_entry.get("value")
            if not name or value is None:
                continue

            # Domain matching
            domain = cookie_entry.get("domain") or cookie_entry.get("host") or ""
            if cookie_entry.get("hostOnly") and isinstance(domain, str):
                domain = domain.lstrip(".")

            if domain:
                if domain.startswith("."):
                    domain_match = host.endswith(domain.lstrip(".")) or host == domain.lstrip(".")
                else:
                    domain_match = host == domain
                if not domain_match:
                    continue

            # Path matching
            cookie_path = cookie_entry.get("path") or "/"
            if not path.startswith(cookie_path):
                continue

            # Secure flag check
            if cookie_entry.get("secure") and not is_secure:
                continue

            cookies[name] = value

        return cookies

    def request(
        self,
        method: str,
        url: str,
        *,
        name: Optional[str] = None,
        cookies: Optional[Dict[str, str]] = None,
        **kwargs: Any,
    ) -> httpx.Response:
        """
        Make an HTTP request with optional name-based cookie injection.

        Args:
            method: HTTP method (GET, POST, etc.)
            url: Request URL
            name: User name for cookie injection (uses default if not specified)
            cookies: Additional cookies to include (merged with name cookies)
            **kwargs: Additional arguments passed to httpx.Client.request()

        Returns:
            httpx.Response
        """
        # Get name-based cookies
        name_cookies = self._get_cookies_for_name(name, url)

        # Merge with explicitly provided cookies (explicit cookies take precedence)
        final_cookies = {**name_cookies, **(cookies or {})}

        if final_cookies:
            kwargs["cookies"] = final_cookies

        resp = self._client.request(method, url, **kwargs)

        self._logger.info(
            "HTTP %s %s name=%s status=%d length=%d",
            method,
            url,
            name or self._default_name or "none",
            resp.status_code,
            len(resp.content)
        )

        return resp

    def get(self, url: str, *, name: Optional[str] = None, **kwargs: Any) -> httpx.Response:
        """Make a GET request."""
        return self.request("GET", url, name=name, **kwargs)

    def post(self, url: str, *, name: Optional[str] = None, **kwargs: Any) -> httpx.Response:
        """Make a POST request."""
        return self.request("POST", url, name=name, **kwargs)

    def put(self, url: str, *, name: Optional[str] = None, **kwargs: Any) -> httpx.Response:
        """Make a PUT request."""
        return self.request("PUT", url, name=name, **kwargs)

    def patch(self, url: str, *, name: Optional[str] = None, **kwargs: Any) -> httpx.Response:
        """Make a PATCH request."""
        return self.request("PATCH", url, name=name, **kwargs)

    def delete(self, url: str, *, name: Optional[str] = None, **kwargs: Any) -> httpx.Response:
        """Make a DELETE request."""
        return self.request("DELETE", url, name=name, **kwargs)

    def options(self, url: str, *, name: Optional[str] = None, **kwargs: Any) -> httpx.Response:
        """Make an OPTIONS request."""
        return self.request("OPTIONS", url, name=name, **kwargs)

    def head(self, url: str, *, name: Optional[str] = None, **kwargs: Any) -> httpx.Response:
        """Make a HEAD request."""
        return self.request("HEAD", url, name=name, **kwargs)

    def close(self) -> None:
        """Close the underlying httpx client."""
        self._client.close()

    def __enter__(self) -> "HTTPClientTool":
        return self

    def __exit__(self, *args: Any) -> None:
        self.close()
